#pragma once

#ifndef QUERYOBJECT_H
#define QUERYOBJECT_H

#include "OrdersSchema.h"

namespace graphql::orders::object {
namespace methods::QueryHas {

template <class TImpl>
concept getOrdersWithParams = requires (TImpl impl, service::FieldParams params, std::optional<int> limitArg)
{
	{ service::AwaitableObject<std::vector<std::shared_ptr<Order>>> { impl.getOrders(std::move(params), std::move(limitArg)) } };
};

template <class TImpl>
concept getOrders = requires (TImpl impl, std::optional<int> limitArg)
{
	{ service::AwaitableObject<std::vector<std::shared_ptr<Order>>> { impl.getOrders(std::move(limitArg)) } };
};

template <class TImpl>
concept getOrderWithParams = requires (TImpl impl, service::FieldParams params, std::string idArg)
{
	{ service::AwaitableObject<std::shared_ptr<Order>> { impl.getOrder(std::move(params), std::move(idArg)) } };
};

template <class TImpl>
concept getOrder = requires (TImpl impl, std::string idArg)
{
	{ service::AwaitableObject<std::shared_ptr<Order>> { impl.getOrder(std::move(idArg)) } };
};

template <class TImpl>
concept beginSelectionSet = requires (TImpl impl, const service::SelectionSetParams params)
{
	{ impl.beginSelectionSet(params) };
};

template <class TImpl>
concept endSelectionSet = requires (TImpl impl, const service::SelectionSetParams params)
{
	{ impl.endSelectionSet(params) };
};

} // namespace methods::QueryHas

class [[nodiscard("unnecessary construction")]] Query final
	: public service::Object
{
private:
	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolveOrders(service::ResolverParams&& params) const;
	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolveOrder(service::ResolverParams&& params) const;

	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolve_typename(service::ResolverParams&& params) const;
	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolve_schema(service::ResolverParams&& params) const;
	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolve_type(service::ResolverParams&& params) const;

	std::shared_ptr<schema::Schema> _schema;

	struct [[nodiscard("unnecessary construction")]] Concept
	{
		virtual ~Concept() = default;

		virtual void beginSelectionSet(const service::SelectionSetParams& params) const = 0;
		virtual void endSelectionSet(const service::SelectionSetParams& params) const = 0;

		[[nodiscard("unnecessary call")]] virtual service::AwaitableObject<std::vector<std::shared_ptr<Order>>> getOrders(service::FieldParams&& params, std::optional<int>&& limitArg) const = 0;
		[[nodiscard("unnecessary call")]] virtual service::AwaitableObject<std::shared_ptr<Order>> getOrder(service::FieldParams&& params, std::string&& idArg) const = 0;
	};

	template <class T>
	struct [[nodiscard("unnecessary construction")]] Model final
		: Concept
	{
		explicit Model(std::shared_ptr<T> pimpl) noexcept
			: _pimpl { std::move(pimpl) }
		{
		}

		[[nodiscard("unnecessary call")]] service::AwaitableObject<std::vector<std::shared_ptr<Order>>> getOrders(service::FieldParams&& params, std::optional<int>&& limitArg) const override
		{
			if constexpr (methods::QueryHas::getOrdersWithParams<T>)
			{
				return { _pimpl->getOrders(std::move(params), std::move(limitArg)) };
			}
			else
			{
				static_assert(methods::QueryHas::getOrders<T>, R"msg(Query::getOrders is not implemented)msg");
				return { _pimpl->getOrders(std::move(limitArg)) };
			}
		}

		[[nodiscard("unnecessary call")]] service::AwaitableObject<std::shared_ptr<Order>> getOrder(service::FieldParams&& params, std::string&& idArg) const override
		{
			if constexpr (methods::QueryHas::getOrderWithParams<T>)
			{
				return { _pimpl->getOrder(std::move(params), std::move(idArg)) };
			}
			else
			{
				static_assert(methods::QueryHas::getOrder<T>, R"msg(Query::getOrder is not implemented)msg");
				return { _pimpl->getOrder(std::move(idArg)) };
			}
		}

		void beginSelectionSet(const service::SelectionSetParams& params) const override
		{
			if constexpr (methods::QueryHas::beginSelectionSet<T>)
			{
				_pimpl->beginSelectionSet(params);
			}
		}

		void endSelectionSet(const service::SelectionSetParams& params) const override
		{
			if constexpr (methods::QueryHas::endSelectionSet<T>)
			{
				_pimpl->endSelectionSet(params);
			}
		}

	private:
		const std::shared_ptr<T> _pimpl;
	};

	explicit Query(std::unique_ptr<const Concept> pimpl) noexcept;

	[[nodiscard("unnecessary call")]] service::TypeNames getTypeNames() const noexcept;
	[[nodiscard("unnecessary call")]] service::ResolverMap getResolvers() const noexcept;

	void beginSelectionSet(const service::SelectionSetParams& params) const override;
	void endSelectionSet(const service::SelectionSetParams& params) const override;

	const std::unique_ptr<const Concept> _pimpl;

public:
	template <class T>
	explicit Query(std::shared_ptr<T> pimpl) noexcept
		: Query { std::unique_ptr<const Concept> { std::make_unique<Model<T>>(std::move(pimpl)) } }
	{
	}

	[[nodiscard("unnecessary call")]] static constexpr std::string_view getObjectType() noexcept
	{
		return { R"gql(Query)gql" };
	}
};

} // namespace graphql::orders::object

#endif // QUERYOBJECT_H
